<?php
namespace App\Http\Controllers;
use App\Models\{User,TimetablePlan as Plan,TimetablePlanEntry as Entry,TimetableRoom as Room};
use App\Support\{AnnualTimetable as A,CentrePlanning as P,TimetableOptimiser as O,PortalActions};
use Illuminate\Http\Request;
use Illuminate\Support\Str;
class AnnualTimetableController extends Controller {
 private function guard(Request $r){$u=PortalActions::actor($r->user());abort_unless(P::allowed($u),403);return$u;}
 private function page(string $name,array $data){return response()->view('annual.'.$name,$data)->header('Cache-Control','private, no-store')->header('Referrer-Policy','no-referrer');}
 private function input(Request $r):array{return$r->validate(['from'=>'required|date_format:Y-m-d','to'=>'required|date_format:Y-m-d','plans'=>'required|array|min:1|max:128','plans.*'=>'required|uuid|distinct','date_mode'=>'required|in:fixed,nearby,year','teaching_dates'=>'nullable|boolean','staff_options'=>'nullable|array|max:128','staff_options.*'=>'array|max:4','staff_options.*.*'=>'required|integer|min:1','room_options'=>'nullable|array|max:128','room_options.*'=>'array|max:4','room_options.*.*'=>'required|integer|min:1','pins'=>'nullable|array|max:1','pins.*'=>'array:date,staff_id,start','pins.*.date'=>'required|date_format:Y-m-d','pins.*.staff_id'=>'required|integer|min:1','pins.*.start'=>'required|date_format:H:i']);}
 public function index(Request $r){$u=$this->guard($r);$d=$r->validate(['from'=>'nullable|date_format:Y-m-d','to'=>'nullable|date_format:Y-m-d','staff'=>'nullable|integer|min:1']);$from=$d['from']??today()->toDateString();$to=$d['to']??today()->addYear()->toDateString();A::range($from,$to);$selectedStaff=(int)($d['staff']??0);$q=Entry::whereDate('work_date','>=',$from)->whereDate('work_date','<=',$to)->when($selectedStaff,fn($q)=>$q->where('staff_id',$selectedStaff));$plans=Plan::where('state','Published')->whereIn('id',$q->select('plan_id'))->orderBy('id')->limit(201)->get();$more=$plans->count()>200;$items=[];
  foreach($plans->take(200)as$p){try{$s=O::eligible($u,$p,$from,$to);$items[]=['id'=>$p->id,'data'=>$s['data'],'eligible'=>true];}catch(\Illuminate\Validation\ValidationException|\Symfony\Component\HttpKernel\Exception\HttpException){$items[]=['id'=>$p->id,'eligible'=>false];}}
  $staff=User::orderBy('name')->get()->filter(fn($x)=>P::staff($x)&&!\App\Support\AccountLifecycle::blocked($x));$rooms=Room::where('active',true)->orderBy('site')->orderBy('name')->get();return$this->page('index',compact('from','to','items','more','staff','rooms','selectedStaff'));
 }
 public function move(Request $r,Plan $plan){$u=$this->guard($r);$d=$r->validate(['date'=>'nullable|date_format:Y-m-d','staff_id'=>'nullable|integer|min:1','start'=>'nullable|date_format:H:i']);\App\Support\TimetableGovernance::guardPlan($u,$plan);abort_unless(P::intact($plan),409);$args=$plan->source['data']['args'];$date=$d['date']??$args['date'];$staffId=(int)($d['staff_id']??$args['staff_id']);$start=$d['start']??$args['start'];$from=min($args['date'],$date);$to=max($args['date'],$date);O::eligible($u,$plan,$from,$to);$single=count($plan->source['data']['rows'])===1;$staff=User::orderBy('name')->get()->filter(fn($x)=>P::staff($x)&&!\App\Support\AccountLifecycle::blocked($x)&&($x->id===$args['staff_id']||in_array($args['kind'],A::TRANSFERABLE,true)));$request=['from'=>$from,'to'=>$to,'plans'=>[$plan->id],'date_mode'=>'year','teaching_dates'=>1,'pins'=>[$plan->id=>['date'=>$date,'staff_id'=>$staffId,'start'=>$start]],'staff_options'=>$staffId!==$args['staff_id']?[$plan->id=>[$staffId]]:[]];return$this->page('move',compact('plan','args','date','staffId','start','staff','request','single'));}
 public function preview(Request $r){$this->guard($r);$v=A::preview($r->user(),$this->input($r));return$this->page('preview',['preview'=>$v,'token'=>(string)Str::uuid()]);}
 public function prepare(Request $r){$this->guard($r);$d=$this->input($r);$x=$r->validate(['source_hash'=>'required|regex:/^[a-f0-9]{64}$/D','request_token'=>'required|uuid','reason'=>'required|string|min:5|max:1000','confirmed'=>'accepted','staff_suitability'=>'nullable|accepted']);$run=A::prepare($r->user(),(int)$r->session()->get('auth_version'),$d,$x['source_hash'],$x['request_token'],$x['reason'],isset($x['staff_suitability']));return to_route('optimiser.show',$run)->with('status','Full-year proposal saved for final review. No reservations have moved.');}
}
